using AutoMapper;using TaskMonitoringApp.Models.DTOs;using TaskMonitoringApp.Models.Entities;using TaskMonitoringApp.Models.Enums;using TaskMonitoringApp.Models.Repositories;using TaskMonitoringApp.Models.Services;using TodoMonitoringApp.Models.Entities;namespace TaskMonitoringApp.Models.Business{    public class TodoServices(ITodoRepository repository, IMapper mapper) : ITodoServices    {        private readonly ITodoRepository _repository = repository;        private readonly IMapper _mapper = mapper;        public async Task AddNewTodo(string UserId, TodoDTO todo)        {            if (todo.Task == null)            {                throw new ArgumentNullException("Missing {TaskID} while creating the new Todo.");            }            await _repository.AddTodoAsync(UserId, _mapper.Map<Todo>(todo));        }        public async Task DeleteTodoById(string UserId, int id)        {            var getTodo = await _repository.GetTodoByIdAsync<Todo>(UserId, id, ResponseDataMode.Model);            getTodo.IsDeleted = true;            getTodo.DeletedOn = DateTime.Now;            await _repository.UpdateTodoAsync(UserId, getTodo);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, Status status)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, status, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, Status status, DateTime selectDate)        {            if (selectDate.Date == DateTime.Today.Date)            {                return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, status, ResponseDataMode.ModelDTO);            }            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, status, selectDate, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, Status.All, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, int taskId, Status status)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, status,  ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, int taskId, Status status, DateTime selectDate)        {            if (selectDate.Date == DateTime.Today.Date)            {                return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, status, ResponseDataMode.ModelDTO);            }            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, status, selectDate, ResponseDataMode.ModelDTO);        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> GetAllTodo(string UserId, int taskId)        {            return await _repository.GetAllTodoAsync<TodoDTOWithTaskDTO>(UserId, taskId, Status.All, ResponseDataMode.ModelDTO);        }        public async Task<TodoDTO> GetTodoById(string UserId, int id)        {            return await _repository.GetTodoByIdAsync<TodoDTO>(UserId, id, ResponseDataMode.ModelDTO);        }        public async Task UpdateTodo(string userId, TodoDTO todo)        {            var todoToUpdate = await _repository.GetTodoByIdAsync<Todo>(userId, todo.Id, ResponseDataMode.Model);            _mapper.Map(todo, todoToUpdate);            await _repository.UpdateTodoAsync(userId, todoToUpdate);        }        public async Task<TodoProgressAnalysisDTO> GetTodoProgressAnalyses(string userId, DateTime forDate)        {            if(forDate.Date == DateTime.Now.Date)            {                return await _repository.GetTodoProgressAnalysesAsync<TodoProgressAnalysisDTO>(userId, ResponseDataMode.ModelDTO);            }            return await _repository.GetTodoProgressAnalysesAsync<TodoProgressAnalysisDTO>(userId, forDate, ResponseDataMode.ModelDTO);        }        public async Task<TodoProgressAnalysisDTO> GetTodoProgressAnalysesWithoutSpAsync(string userId, DateTime forDate)        {            if (forDate.Date == DateTime.Now.Date)            {                await GenerateTodosFromTasksAsync(userId);            }            return await _repository.UpsertAndGetTodoProgressAnalysesWithoutSpAsync(userId, forDate);        }        public async Task<TodoProgressAnalysisDTO> GetTodoProgressAnalyses(string userId, int taskId)        {            return await _repository.GetTodoProgressAnalysesAsync(userId, taskId);        }        public async Task UpdateTodoStatus(string userId, int todoId, Status statusToChange)        {            await _repository.UpdateTodoStatusAsync(userId, todoId, statusToChange);        }        public async Task UpdateTodoNotes(string userId, int todoId, string notes)        {            await _repository.UpdateTodoNotesAsync(userId, todoId, notes);        }        public async Task AddBulkTodos(string userId, BulkTodoCreateDTO bulkDto)        {            bulkDto.UserId = userId;            await _repository.AddBulkTodosAsync(bulkDto);        }        public async Task GenerateTodosFromTasksAsync(string userId)        {            var today = DateTime.Today; // Start of today            var currentDateTime = DateTime.Now;            var tomorrow = today.AddDays(1).AddMinutes(-1); // Start of tomorrow as per original logic            int currentWeekday = ((int)currentDateTime.DayOfWeek + 6) % 7;             var currentWeekdayEnum = (Weekly)currentWeekday;             var candidateTasks = await _repository.GetCandidateTasksForTodoAsync(userId);            var existingTaskIds = await _repository.GetExistingTodoTaskIdsAsync(userId, today, tomorrow);            var existingTaskIdsHashSet = new HashSet<int>(existingTaskIds);            var todosToInsert = new List<Todo>();            foreach (var task in candidateTasks)            {                bool repeatConditionMet =                    task.Repeat == RepeatType.RunOnce ||                    task.Repeat == RepeatType.Daily ||                    (task.Repeat == RepeatType.Weekly && task.RepeatWeekList != null && task.RepeatWeekList.Contains(currentWeekdayEnum));                if (!repeatConditionMet)                    continue;                if (existingTaskIdsHashSet.Contains(task.Id))                    continue;                todosToInsert.Add(new Todo                {                    EndDate = tomorrow,                    Status = Status.Running,                    CreatedOn = currentDateTime,                    UpdatedOn = currentDateTime,                    TaskId = task.Id,                    UserId = userId,                    IsDeleted = false                });            }            if (todosToInsert.Any())            {                await _repository.AddTodosBulkAsync(todosToInsert);            }        }        public async Task<IEnumerable<TodoDTOWithTaskDTO>> AddAndGetTodosFromTaskAsync(string userId, Status status)        {            if (status == Status.Running)            {                await GenerateTodosFromTasksAsync(userId);            }            return await _repository.GetAllTodosFromTaskWithoutSpAsync<TodoDTOWithTaskDTO>(userId, status, ResponseDataMode.ModelDTO);        }    }}